 */

plugins {
    // Apply the java-library plugin for API and implementation separation.

    id("java")
    id("checkstyle")
    id("jacoco")
    `java-library`
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

group = "com.distributed.kvstore"
version = "1.0-SNAPSHOT"

checkstyle {
    toolVersion = "13.8.0"
    configFile = rootProject.file("config/checkstyle/checkstyle.xml")
    isIgnoreFailures = false
    isShowViolations = true
}

tasks.test {
    useJUnitPlatform()
    testLogging {
        events("passed", "failed", "skipped")
        showStandardStreams = true
    }
    systemProperties(System.getProperties().map { it.key.toString() to it.value }.toMap())
    finalizedBy(tasks.jacocoTestReport)
}

tasks.jacocoTestReport { dependsOn(tasks.test); reports { xml.required = true; html.required = true } }

tasks.jacocoTestCoverageVerification { violationRules { rule { limit { minimum = "0.90".toBigDecimal() } } } }
